import { useState } from 'react';
import { 
  Box, 
  IconButton, 
  Drawer, 
  MenuItem, 
  Divider, 
  Button,
  ListItemIcon,
  ListItemText
} from '@mui/material';
import { useLocation, Link } from 'react-router-dom';
import MenuIcon from '@mui/icons-material/Menu';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import BarChartIcon from '@mui/icons-material/BarChart';
import HomeIcon from '@mui/icons-material/Home';
import NoteIcon from '@mui/icons-material/Note';
import ArticleIcon from '@mui/icons-material/Article';
import WorkIcon from '@mui/icons-material/Work';
import AccountBalanceIcon from '@mui/icons-material/AccountBalance';
import PersonIcon from '@mui/icons-material/Person';
import LanguageIcon from '@mui/icons-material/Language';
import Brightness4Icon from '@mui/icons-material/Brightness4';
import PersonAddIcon from '@mui/icons-material/PersonAdd';
import LockResetIcon from '@mui/icons-material/LockReset';
import LogoutIcon from '@mui/icons-material/Logout';
import LanguageSwitchComponent from './LanguageSwitch';
import ThemeSwitch from './ThemeSwitch';
import { translations } from './translations';
import { useUser } from '../../../context/UserContext';
import UserService from '../../../services/UserService';
import PasswordResetModal from './PasswordResetModal';

const MobileDrawer = ({ 
  language, 
  toggleLanguage, 
  toggleTheme, 
  handleLoginOpen, 
  handleSignupOpen 
}) => {
  const [open, setOpen] = useState(false);
  const [passwordResetOpen, setPasswordResetOpen] = useState(false);
  const { userState, setUser } = useUser();

  const toggleDrawer = (newOpen) => () => setOpen(newOpen);

  const handleLogout = async () => {
    const userData = await UserService.getNonuserJWT();
    setUser(userData);
    setOpen(false);
  };

  const handlePasswordResetOpen = () => {
    setPasswordResetOpen(true);
    setOpen(false);
  };

  const handleNavItemClick = (path) => {
    if (location.pathname === path) {
      // 如果已经在当前页面，只关闭 Drawer
      setOpen(false);
    }
    // 否则交给 Link 正常跳转
  };

  // 导航菜单项配置
  const navItems = [
    { path: '/', icon: HomeIcon, label: translations[language].home },
    { path: '/notes', icon: NoteIcon, label: translations[language].notes },
    { path: '/blogs', icon: ArticleIcon, label: translations[language].blogs },
    { path: '/projects', icon: WorkIcon, label: translations[language].projects },
    { path: '/fin', icon: AccountBalanceIcon, label: translations[language].finance },
    // { path: '/profile', icon: PersonIcon, label: translations[language].profile },
    // 只有 is_superuser 为 true 的用户才能看到 Dashboard 菜单项
    ...(userState?.is_superuser ? [{ path: '/dashboard', icon: BarChartIcon, label: translations[language].dashboard }] : []),
  ];

  return (
    <Box sx={{ display: { xs: 'flex', md: 'none' }, gap: 1 }}>
      <IconButton aria-label="Menu button" onClick={toggleDrawer(true)}>
        <MenuIcon />
      </IconButton>
      <Drawer
        anchor="top"
        open={open}
        onClose={toggleDrawer(false)}
        PaperProps={{
          sx: { 
            top: 'var(--template-frame-height, 0px)', 
            borderBottomLeftRadius: '5px',
            borderBottomRightRadius: '5px'
          },
        }}
      >
        <Box sx={{ p: 1.5, backgroundColor: 'background.default' }}>
          <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 1 }}>
            <IconButton onClick={toggleDrawer(false)} size="small">
              <CloseRoundedIcon />
            </IconButton>
          </Box>
          
          {/* 导航菜单 */}
          {navItems.map(({ path, icon: Icon, label }) => (
            <MenuItem 
              key={path} 
              component={Link} 
              to={path}
              onClick={() => handleNavItemClick(path)} 
              sx={{ py: 0.5, minHeight: 40 }}
            >
              <ListItemIcon sx={{ mr: 1.5, minWidth: 36 }}>
                <Icon fontSize="medium" />
              </ListItemIcon>
              <ListItemText 
                primary={label} 
                primaryTypographyProps={{ fontSize: '16px' }}
              />
            </MenuItem>
          ))}
          
          <Divider sx={{ my: 1.5 }} />
          
          {/* 设置选项 */}
          <MenuItem sx={{ py: 0.5, minHeight: 40 }}>
            <ListItemIcon sx={{ mr: 1.5, minWidth: 36 }}>
              <LanguageIcon fontSize="medium" />
            </ListItemIcon>
            <LanguageSwitchComponent onClick={toggleLanguage} />
          </MenuItem>
          
          <MenuItem sx={{ py: 0.5, minHeight: 40 }}>
            <ListItemIcon sx={{ mr: 1.5, minWidth: 36 }}>
              <Brightness4Icon fontSize="medium" />
            </ListItemIcon>
            <ThemeSwitch onClick={toggleTheme} />
          </MenuItem>
          
          <Divider sx={{ my: 1.5 }} />

          {/* 用户状态相关按钮 */}
          {userState.user_id === 0 ? (
            <Box sx={{ display: 'flex', gap: 1 }}>
              <Button
                color="primary"
                variant="outlined"
                size="medium"
                onClick={handleLoginOpen}
                startIcon={<PersonIcon />}
                sx={{ flex: 1, fontSize: '14px' }}
              >
                {translations[language].login}
              </Button>
              <Button
                color="primary"
                variant="contained"
                size="medium"
                onClick={handleSignupOpen}
                startIcon={<PersonAddIcon />}
                sx={{ flex: 1, fontSize: '14px' }}
              >
                {translations[language].signup}
              </Button>
            </Box>
          ) : (
            <>
              <Box sx={{ display: 'flex', gap: 1, mb: 1 }}>
                <Button
                  color="primary"
                  variant="outlined"
                  size="medium"
                  onClick={handlePasswordResetOpen}
                  startIcon={<LockResetIcon />}
                  sx={{ flex: 1, fontSize: '14px' }}
                >
                  {translations[language].password_reset_mobile}
                </Button>
                <Button
                  color="primary"
                  variant="contained"
                  size="medium"
                  onClick={handleLogout}
                  startIcon={<LogoutIcon />}
                  sx={{ flex: 1, fontSize: '14px' }}
                >
                  {translations[language].logout}
                </Button>
              </Box>
              <Button
                color="info"
                variant="text"
                size="medium"
                disabled
                fullWidth
                sx={{ textTransform: 'none', justifyContent: 'center', fontSize: '14px' }}
                startIcon={<PersonIcon />}
              >
                {userState.username}
              </Button>
            </>
          )}
        </Box>
      </Drawer>

      <PasswordResetModal
        open={passwordResetOpen}
        onClose={() => setPasswordResetOpen(false)}
        language={language}
      />
    </Box>
  );
};

export default MobileDrawer;