import { useContext, useState } from 'react';
import { alpha, styled } from '@mui/material/styles';
import { AppBar, Box, Toolbar, Container, IconButton } from '@mui/material';
import PermIdentityIcon from '@mui/icons-material/PermIdentity';
import { SettingsContext } from '../../../context/SettingsContext';
import { useUser } from '../../../context/UserContext';
import DesktopNav from './DesktopNav';
import MobileDrawer from './MobileDrawer';
import UserMenu from './UserMenu';
import { LoginModal, SignupModal } from './AuthModals';

const StyledToolbar = styled(Toolbar)(({ theme }) => ({
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'space-between',
  flexShrink: 0,
  borderRadius: `calc(${theme.shape.borderRadius}px + 8px)`,
  backdropFilter: 'blur(24px)',
  border: '1px solid',
  borderColor: (theme.vars || theme).palette.divider,
  backgroundColor: theme.vars
    ? `rgba(${theme.vars.palette.background.defaultChannel} / 0.4)`
    : alpha(theme.palette.background.default, 0.4),
  boxShadow: (theme.vars || theme).shadows[1],
  padding: '8px 12px',
}));

export default function CustomAppBar() {
  const { language, toggleLanguage, themeMode, toggleTheme } = useContext(SettingsContext);
  const { userState } = useUser();

  // 登录/注册模态框状态
  const [loginOpen, setLoginOpen] = useState(false);
  const [signupOpen, setSignupOpen] = useState(false);

  const handleLoginOpen = () => setLoginOpen(true);
  const handleLoginClose = () => setLoginOpen(false);
  const handleSignupOpen = () => setSignupOpen(true);
  const handleSignupClose = () => setSignupOpen(false);

  // Dynamic button color based on theme
  const buttonColor = themeMode === 'dark' ? '#64B5F6' : '#13479c';

  return (
    <AppBar
      position="absolute"
      enableColorOnDark
      sx={{
        boxShadow: 0,
        bgcolor: 'transparent',
        backgroundImage: 'none',
        mt: 'calc(var(--template-frame-height, 0px) + 28px)'
      }}
    >
      <Container maxWidth="lg">
        <StyledToolbar variant="dense" disableGutters>
          {/* 桌面导航组件 */}
          <DesktopNav 
            language={language} 
            toggleLanguage={toggleLanguage} 
            themeMode={themeMode}
            toggleTheme={toggleTheme} 
          />

          {/* 用户认证按钮/菜单 - 仅桌面版 */}
          <Box sx={{ display: { xs: 'none', md: 'flex' }, gap: 1.5, alignItems: 'center' }}>
            {userState.user_id === 0 ? (
              <IconButton
                onClick={handleLoginOpen}
                sx={{ 
                  mr: "10px",
                  padding: '1px',
                  color: buttonColor,
                  '&:hover': {
                    color: themeMode === 'dark' ? '#03a9f4' : '#1670C5',
                    backgroundColor: 'rgba(0, 0, 0, 0.04)', // 轻微的背景色变化
                  }
                }}
                aria-label="Login"
              >
                <PermIdentityIcon sx={{ fontSize: '1.8rem' }} />
              </IconButton>
            ) : (
              <UserMenu language={language} themeMode={themeMode}/>
            )}
          </Box>

          {/* 移动端抽屉菜单 */}
          <MobileDrawer
            language={language}
            toggleLanguage={toggleLanguage}
            toggleTheme={toggleTheme}
            handleLoginOpen={handleLoginOpen}
            handleSignupOpen={handleSignupOpen}
          />
        </StyledToolbar>
      </Container>

      {/* 登录/注册模态框 */}
      <LoginModal 
        open={loginOpen} 
        handleClose={handleLoginClose} 
        handleSignupOpen={handleSignupOpen} 
      />
      
      <SignupModal 
        open={signupOpen} 
        handleClose={handleSignupClose} 
        handleLoginOpen={handleLoginOpen} 
      />
    </AppBar>
  );
}